import { privateJson } from './session.js';
if(!document.querySelector('link[href="/coaching.css"]')){const css=document.createElement('link');css.rel='stylesheet';css.href='/coaching.css';document.head.append(css);}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mark='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m3 17 5-5 4 3 8-10M14 5h6v6M3 21h18"/></svg>';
export function formatFact(f){const v=f?.value;if(!Number.isFinite(v))return 'Unavailable';if(f.unit==='s/km'){const n=Math.round(Math.abs(v));return (v<0?'−':'')+Math.floor(n/60)+':'+String(n%60).padStart(2,'0')+' /km';}if(f.unit==='m')return new Intl.NumberFormat('en-AU',{maximumFractionDigits:2}).format(v/1000)+' km';if(f.unit==='s'){const n=Math.round(v);return Math.floor(n/60)+':'+String(n%60).padStart(2,'0');}return new Intl.NumberFormat('en-AU',{maximumFractionDigits:1}).format(v)+(f.unit==='count'?'':f.unit==='bpm'?' bpm':f.unit==='spm'?' spm':f.unit==='/10'?' /10':' '+f.unit);}
export async function mountCoaching(root,{settings=false}={}){
 root.classList.add('ai-space');root.id=settings?'ai-settings':'coaching';root.innerHTML='<p role="status">Opening your AI preferences…</p>';
 let state,busy=false,message='',destroyed=false,request=0;
 const notice=()=>`<details class="ai-sharing"><summary>What would be shared?</summary><p>Running distance, duration, pace, full-kilometre splits, available heart-rate and cadence summaries, elevation and structured effort answers. Up to sixty recent run summaries plus history totals; each briefing uses your own record.</p><p>Names, email, exact dates, routes, GPS coordinates, screenshots, free-text notes, passwords and API keys are excluded. Google receives relative timing and source labels.</p><p>On the free service, Google may use submissions to improve products and human reviewers may process them. Google’s unpaid-service terms also restrict personal or sensitive submissions; your choice records permission within this app and does not change those terms. <a href="https://ai.google.dev/gemini-api/terms" target="_blank" rel="noopener noreferrer">Read Google’s data terms ↗</a></p><p>Switching off stops new requests and hides saved briefings. A request already sent cannot be recalled; existing reports remain in your private record.</p></details>`;
 const template=(text,facts)=>esc(text).replace(/\{([\w.]+)\}/g,(_,id)=>esc(formatFact(facts.get(id))));
 function chart(item,review,facts){const suffix={pace:'paceSPerKm',distance:'distanceM',heart_rate:'hrBpm'}[item.type],title={pace:'Recorded pace',distance:'Running distance',heart_rate:'Average heart rate'}[item.type],rows=item.sessionIds.map(ref=>({ref,f: facts.get(ref+'.'+suffix),s:review.evidence.sessions.find(s=>s.ref===ref)})),max=Math.max(...rows.map(r=>r.f?.value||0),1);return `<div class="ai-chart"><h3>${title}</h3><p class="ai-fine">Source values · ${item.type==='pace'?'lower is faster':'recorded summaries'}</p><table><caption class="sr-only">${title} for cited runs</caption><thead><tr><th>Run</th><th>Recorded value</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row"><a href="/app.html?activity=${encodeURIComponent(review.mapping[r.ref])}">${r.s?.daysAgo===0?'Analysis day':esc(r.s?.daysAgo)+' days before analysis'} ↗</a></th><td><span class="ai-chart-bar" style="--amount:${Math.max(1,(r.f?.value||0)/max*100)}%" aria-hidden="true"></span><strong>${esc(formatFact(r.f))}</strong></td></tr>`).join('')}</tbody></table></div>`;}
 function render(){if(destroyed||!root.isConnected)return;const consent=state?.consent||{},enabled=consent.enabled===true,unanswered=consent.enabled==null,review=state?.review,facts=new Map((review?.evidence.facts||[]).map(f=>[f.id,f]));
  root.innerHTML=`<div class="ai-header"><div><span class="section-caption">${settings?'AI / YOUR CHOICE':'THE COACHING BRIEF'}</span><h2>${settings?'Your intelligence.<br><em>Your permission.</em>':enabled&&review?'THE SIGNAL.<br><em>BEHIND THE SESSIONS.</em>':'MORE THAN NUMBERS.<br><em>YOUR CALL.</em>'}</h2></div><span class="ai-status">${mark}${unanswered?'Your choice':enabled?'Gemini enabled':'AI is off'}</span></div>
  ${!enabled||settings?`<div class="ai-consent"><p>${unanswered?'Would you like Gemini to analyse your running record and find patterns across your sessions?':enabled?'Gemini is allowed to analyse your running record when you request a briefing.':'Your runs and charts work as usual. Your running record is not sent for new Gemini briefings.'}</p><p class="ai-fine">Optional. Saved to your account, across devices. Change it here${settings?'':' or in Account → AI preferences'} whenever you like.</p>${notice()}<div class="ai-actions">${enabled?'<button class="secondary-button" data-ai="deny">Turn AI off</button>':`<button class="secondary-button" data-ai="allow">Allow Gemini analysis ↗</button>${unanswered?'<button class="secondary-button" data-ai="deny">Keep AI off</button>':''}`}</div></div>`:''}
  ${enabled&&!settings?`${review?`<div class="ai-verdict"><span class="section-caption">YOUR RECORD, READ TOGETHER</span><h3>${template(review.report.verdict.text,facts)}</h3><p class="ai-fine">${review.stale?'New data is waiting for analysis. Showing your previous briefing.':'Based on your imported running history.'} Generated ${esc(new Date(review.generatedAt).toLocaleString('en-AU'))}</p></div><div class="ai-findings">${review.report.findings.map((f,i)=>`<article><div class="ai-finding-top"><span class="section-caption">0${i+1} / ${esc(f.kind)}</span><span>${f.assessment==='measured'?'Measured finding':'Coach interpretation'}</span></div><h3>${template(f.headline,facts)}</h3><p>${template(f.explanation,facts)}</p><div class="ai-next"><span>Next</span><p>${template(f.nextAction,facts)}</p></div><details><summary>Show the evidence</summary><dl>${f.factIds.map(id=>`<div><dt>${esc(facts.get(id)?.label)}</dt><dd>${esc(formatFact(facts.get(id)))}</dd></div>`).join('')}</dl><div class="ai-source-links">${[...new Set(f.factIds.flatMap(id=>facts.get(id)?.sessionIds||[]))].map((ref,j)=>`<a href="/app.html?activity=${encodeURIComponent(review.mapping[ref])}">Open cited run ${j+1} ↗</a>`).join('')}</div></details></article>`).join('')}</div>${review.report.charts.length?`<details class="ai-visuals"><summary>Explore the comparisons</summary><div class="ai-charts">${review.report.charts.map(c=>chart(c,review,facts)).join('')}</div></details>`:''}`:`<p class="ai-invitation">Your training has a story. Ask Gemini to connect the patterns, explain the numbers and suggest what to pay attention to next.</p>`}<div class="ai-actions"><button class="primary-button" data-ai="generate" ${!state.configured||busy?'disabled':''}>${busy?'Reading your training…':review&&!review.stale?'Briefing is up to date':review?'Update my briefing':'Generate my briefing'} ${busy?'':'↗'}</button><a class="text-button" href="/account#ai-settings">AI preferences</a></div><p class="ai-fine">${!state.configured?'Gemini is not configured for free-tier generation on this server.':'Gemini · high thinking · maximum three new briefings per UTC day · no automatic paid fallback.'}</p>`:''}
  <p class="ai-message" role="status" aria-live="polite">${esc(message)}</p>`;
  root.querySelectorAll('[data-ai]').forEach(button=>{button.disabled=busy||(button.dataset.ai==='generate'&&(!state.configured||review&&!review.stale));button.addEventListener('click',()=>act(button.dataset.ai));});
 }
 async function load(){const token=++request;const next=await privateJson('/api/private?route=ai-review');if(token===request){state=next;render();}}
 async function act(action){if(busy)return;busy=true;message=action==='generate'?'Gemini is examining your evidence. Your runs stay available.':'Saving your choice…';render();try{
   if(action==='generate'){const review=await privateJson('/api/private?route=ai-review',{method:'POST'});state.review=review;message='Your briefing is ready.';}
   else{const consent=await privateJson('/api/private?route=ai-consent',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:action==='allow'})});state={...state,consent,review:null};message=consent.enabled?'Permission saved. Generate a briefing when you are ready.':'AI is off. No new analysis requests will be sent.';try{localStorage.setItem('mfa-ai-preference-changed',String(Date.now()));}catch{}await load();}
  }catch(e){message=e.message;}finally{busy=false;render();root.querySelector('.ai-message')?.setAttribute('tabindex','-1');root.querySelector('.ai-message')?.focus({preventScroll:true});}}
 const changed=event=>{if(event.key==='mfa-ai-preference-changed'){state=null;root.innerHTML='<p role="status">Updating your AI preference…</p>';load().catch(e=>{root.textContent=e.message;});}};addEventListener('storage',changed);addEventListener('pagehide',()=>{destroyed=true;removeEventListener('storage',changed);},{once:true});
 try{await load();}catch(e){root.innerHTML=`<p role="status">${esc(e.message)}</p><a href="/account#ai-settings">Open AI preferences ↗</a>`;}
}
